  "sources": ["src/app/components/shop/cart/cart.component.scss"],
  "sourcesContent": ["$gold: #C9A054;\r\n$dark: #1A2518;\r\n\r\n.cart-page {\r\n  padding: 32px 0 48px;\r\n  background: #f8f7f4;\r\n}\r\n\r\n// ---- Header ----\r\n.cp__header {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  margin-bottom: 24px;\r\n}\r\n\r\n.cp__title {\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 24px;\r\n  font-weight: 700;\r\n  color: $dark;\r\n  margin: 0;\r\n}\r\n\r\n.cp__count {\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  color: #999;\r\n  background: #fff;\r\n  border: 1px solid #eeebe5;\r\n  padding: 4px 14px;\r\n  border-radius: 20px;\r\n}\r\n\r\n// ---- Cart Items ----\r\n.cp__items {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n}\r\n\r\n.cp__item {\r\n  display: flex;\r\n  gap: 18px;\r\n  background: #fff;\r\n  border: 1px solid #eeebe5;\r\n  border-radius: 10px;\r\n  padding: 18px;\r\n  transition: border-color 0.15s;\r\n\r\n  &:hover { border-color: #ddd; }\r\n\r\n  @media (max-width: 575px) {\r\n    flex-direction: column;\r\n    gap: 14px;\r\n  }\r\n}\r\n\r\n.cp__item-img-wrap {\r\n  flex-shrink: 0;\r\n  width: 100px;\r\n  height: 100px;\r\n  border-radius: 8px;\r\n  overflow: hidden;\r\n  background: #f5f3ee;\r\n\r\n  @media (max-width: 575px) {\r\n    width: 100%;\r\n    height: 180px;\r\n  }\r\n}\r\n\r\n.cp__item-img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  display: block;\r\n}\r\n\r\n.cp__item-body {\r\n  flex: 1;\r\n  min-width: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n}\r\n\r\n.cp__item-top {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-start;\r\n  gap: 12px;\r\n  margin-bottom: 12px;\r\n}\r\n\r\n.cp__item-name {\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 15px;\r\n  font-weight: 600;\r\n  margin: 0 0 2px;\r\n  line-height: 1.4;\r\n\r\n  a {\r\n    color: $dark;\r\n    text-decoration: none;\r\n    &:hover { color: $gold; }\r\n  }\r\n}\r\n\r\n.cp__item-variant {\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 12px;\r\n  color: #aaa;\r\n}\r\n\r\n.cp__item-remove {\r\n  background: none;\r\n  border: none;\r\n  color: #ccc;\r\n  font-size: 18px;\r\n  cursor: pointer;\r\n  padding: 4px;\r\n  flex-shrink: 0;\r\n  transition: color 0.15s;\r\n\r\n  &:hover { color: #dc2626; }\r\n}\r\n\r\n.cp__item-bottom {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n\r\n// Quantity\r\n.cp__qty {\r\n  display: flex;\r\n  align-items: center;\r\n  border: 1.5px solid #e8e5de;\r\n  border-radius: 6px;\r\n  overflow: hidden;\r\n  background: #faf9f6;\r\n\r\n  ::ng-deep .cp__qty-btn,\r\n  ::ng-deep .cp__qty-btn button {\r\n    width: 34px !important;\r\n    height: 34px !important;\r\n    background: transparent !important;\r\n    border: none !important;\r\n    color: $dark !important;\r\n    cursor: pointer !important;\r\n    display: flex !important;\r\n    align-items: center !important;\r\n    justify-content: center !important;\r\n    padding: 0 !important;\r\n    min-width: unset !important;\r\n\r\n    &:hover { background: rgba($gold, 0.08) !important; }\r\n\r\n    i { font-size: 14px !important; }\r\n  }\r\n}\r\n\r\n.cp__qty-val {\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  color: $dark;\r\n  min-width: 36px;\r\n  text-align: center;\r\n}\r\n\r\n.cp__item-price {\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 16px;\r\n  font-weight: 700;\r\n  color: $dark;\r\n}\r\n\r\n// ---- Summary ----\r\n.cp__summary {\r\n  background: #fff;\r\n  border: 1px solid #eeebe5;\r\n  border-radius: 10px;\r\n  padding: 28px 24px;\r\n  position: sticky;\r\n  top: 20px;\r\n\r\n  @media (max-width: 575px) { padding: 22px 18px; }\r\n}\r\n\r\n.cp__summary-title {\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 14px;\r\n  font-weight: 700;\r\n  color: $dark;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.8px;\r\n  margin-bottom: 20px;\r\n  padding-bottom: 16px;\r\n  border-bottom: 1px solid #f0ede8;\r\n}\r\n\r\n.cp__summary-rows {\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.cp__sum-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 14px;\r\n  color: #777;\r\n  padding: 8px 0;\r\n\r\n  span:last-child { font-weight: 500; color: $dark; }\r\n}\r\n\r\n.cp__sum-muted { color: #bbb !important; font-weight: 400 !important; }\r\n\r\n.cp__sum-total {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 18px;\r\n  font-weight: 700;\r\n  color: $dark;\r\n  padding: 18px 0;\r\n  margin-bottom: 20px;\r\n  border-top: 1.5px solid #e8e5de;\r\n}\r\n\r\n.cp__btn-checkout {\r\n  display: block;\r\n  width: 100%;\r\n  padding: 14px;\r\n  background: $dark;\r\n  color: #fff;\r\n  border: none;\r\n  border-radius: 6px;\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 13px;\r\n  font-weight: 600;\r\n  letter-spacing: 0.8px;\r\n  text-transform: uppercase;\r\n  text-align: center;\r\n  text-decoration: none;\r\n  transition: background 0.2s;\r\n  margin-bottom: 10px;\r\n\r\n  &:hover { background: $gold; color: $dark; }\r\n}\r\n\r\n.cp__btn-continue {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 6px;\r\n  width: 100%;\r\n  padding: 12px;\r\n  background: none;\r\n  border: 1.5px solid #e8e5de;\r\n  border-radius: 6px;\r\n  font-family: 'Poppins', sans-serif;\r\n  font-size: 13px;\r\n  font-weight: 600;\r\n  color: #999;\r\n  text-decoration: none;\r\n  text-align: center;\r\n  transition: all 0.15s;\r\n\r\n  i { font-size: 16px; }\r\n\r\n  &:hover { border-color: $dark; color: $dark; }\r\n}\r\n"],
