teY(-2px);\r\n              box-shadow: 0 4px 12px rgba(217, 77, 37, 0.4);\r\n            }\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n  \r\n  .empty-cart-box {\r\n    text-align: center;\r\n    padding: 50px 30px;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    min-height: 250px;\r\n    \r\n    i {\r\n      font-size: 80px;\r\n      color: #1E83CA;\r\n      margin-bottom: 20px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 120px;\r\n      height: 120px;\r\n      background: linear-gradient(135deg, rgba(30, 131, 202, 0.1) 0%, rgba(30, 131, 202, 0.05) 100%);\r\n      border-radius: 50%;\r\n      position: relative;\r\n      animation: cartIconPulse 2s ease-in-out infinite;\r\n      \r\n      &::before {\r\n        content: '';\r\n        position: absolute;\r\n        width: 100px;\r\n        height: 100px;\r\n        border: 2px solid rgba(30, 131, 202, 0.2);\r\n        border-radius: 50%;\r\n        animation: cartIconRing 2s ease-in-out infinite;\r\n      }\r\n    }\r\n    \r\n    h5 {\r\n      font-size: 18px;\r\n      font-weight: 600;\r\n      color: #333;\r\n      margin: 0;\r\n      line-height: 1.5;\r\n    }\r\n  }\r\n  \r\n  @keyframes cartIconPulse {\r\n    0%, 100% {\r\n      transform: scale(1);\r\n      opacity: 1;\r\n    }\r\n    50% {\r\n      transform: scale(1.05);\r\n      opacity: 0.9;\r\n    }\r\n  }\r\n  \r\n  @keyframes cartIconRing {\r\n    0% {\r\n      transform: scale(1);\r\n      opacity: 1;\r\n    }\r\n    100% {\r\n      transform: scale(1.3);\r\n      opacity: 0;\r\n    }\r\n  }\r\n}\r\n\r\n// Responsive adjustments\r\n@media (max-width: 767px) {\r\n  .onhover-dropdown {\r\n    &.cart-open {\r\n      .onhover-div {\r\n        position: fixed !important;\r\n        left: 50% !important;\r\n        right: auto !important;\r\n        transform: translateX(-50%) !important;\r\n        top: 80px !important;\r\n        width: calc(100vw - 40px) !important;\r\n        max-width: 400px !important;\r\n        margin: 0 auto;\r\n        z-index: 1001 !important;\r\n        opacity: 1 !important;\r\n        visibility: visible !important;\r\n        display: block !important;\r\n      }\r\n    }\r\n    \r\n    .onhover-div {\r\n      display: none;\r\n    }\r\n  }\r\n  \r\n  .onhover-div.fixed-cart {\r\n    .cart-list {\r\n      > li {\r\n        .drop-cart.horizontal-layout {\r\n          flex-wrap: wrap;\r\n\r\n          .drop-image {\r\n            width: 60px;\r\n            height: 60px;\r\n          }\r\n\r\n          .drop-contain {\r\n            flex: 1;\r\n            min-width: 120px;\r\n          }\r\n\r\n          .cart-actions {\r\n            width: 100%;\r\n            flex-direction: row;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n  \r\n  .empty-cart-box {\r\n    text-align: center;\r\n    padding: 50px 30px !important;\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    min-height: 300px;\r\n    \r\n    i {\r\n      font-size: 80px;\r\n      color: #1E83CA;\r\n      margin-bottom: 20px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 120px;\r\n      height: 120px;\r\n      background: linear-gradient(135deg, rgba(30, 131, 202, 0.1) 0%, rgba(30, 131, 202, 0.05) 100%);\r\n      border-radius: 50%;\r\n      position: relative;\r\n      animation: cartIconPulse 2s ease-in-out infinite;\r\n      \r\n      &::before {\r\n        content: '';\r\n        position: absolute;\r\n        width: 100px;\r\n        height: 100px;\r\n        border: 2px solid rgba(30, 131, 202, 0.2);\r\n        border-radius: 50%;\r\n        animation: cartIconRing 2s ease-in-out infinite;\r\n      }\r\n    }\r\n    \r\n    h5 {\r\n      font-size: 18px;\r\n    